bookInfoRule.intro:
$.data.book.description
<js>if(!result){
token=java.get('token');
var time = Math.round(new Date()/1000);
result='❗️通过离线下载这本书，刷每日阅读，离线下载一直显示正在启动的话是已经开始了，不用管它，因为是一直循环访问网址，手机可能会发烫，取消离线下载即可停止,如果取消很久还是发烫，请杀后台❗️';
list=[
"appId=",
"osType=2",
"product=1",
"sysVer=10",
"time="+time,
"token="+token,
"ver=2.1.3",
"packageName=com.lestory.jihua.an",
"lang-app=zh-Hans",
"lang=zh-hans",
"locale=CN"
]

function sign(list){
var sb='';
sb+="Fb0gqLMSf5Android";
list=list.sort();
i=0;
while(i<list.length){
if(i==0){
sb+=list[i]
}else{
    if(list[i].match(/lang-app=/)){  
      i2=i+1;
     i3=i2+1;
     if (list[i2] != null && list[i2].match(/lang=/)) {
                        sb+="&";
                        sb+=list[i2];

                        sb+="&";
                        sb+=list[i];

                        i = i3;
                    }
           }
                sb+="&";
                sb+=list[i];             
      }
i++
}
sb+="AEdDtho2CjiH901aVK7swFqclu6NmzJ4";
return String(java.md5Encode(sb)).toUpperCase()
}

s=sign(list);

json={"product":"1","ver":"2.1.3","sysVer":"10","locale":"CN","token":String(token),"lang-app":"zh-Hans","appId":"","osType":"2","time":time,"packageName":"com.lestory.jihua.an","lang":"zh-hans","sign":String(s)}

option={
"method": "POST",
"body": JSON.stringify(json)
}
url='http://api.lestory.cn/user/center,'+JSON.stringify(option);
aaa=JSON.parse(String(java.ajax(url))).data;
result+'\n剩余书币：'+aaa.remain+'\n今日获得书币：'+aaa.coin_today+'\n今日阅读：'+aaa.today_read_duration+'分钟\n点右上角刷新此页面更新数据'
}else{result=result}</js>

